--- from: Assets/BundleResources/Prefabs/ResidentEvent/SpecialGiftPackageDialog.prefab > name: SpecialGiftPackageDialog
---@class WhiteLevelGiftDialog
---@field Env                           	WhiteLevelGiftDialog                    
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field FX_glow2                      	UnityEngine.RectTransform               
---@field AnmRoot                       	UnityEngine.RectTransform               
