---@field BtnReward                     	UnityEngine.RectTransform               
---@field BtnExplain                    	UnityEngine.RectTransform
---@field ListView                      	SuperScrollView.LoopListView2
local WhiteLevelGiftDialog = Class("WhiteLevelGiftDialog")

function WhiteLevelGiftDialog:__init()
    self.data = nil
end

function WhiteLevelGiftDialog:__delete()
    self.data = nil
    self.controller = nil
end

function WhiteLevelGiftDialog:Awake()
    ---@type WhiteLevelGiftComponent
    local whiteLevelGiftComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.WhiteLevelGiftComponent)
    self.data = whiteLevelGiftComponent.whiteLevelGift
    self.__EventSdkEvent = Events.AddListener(Constants.EventNames.EVENT_SDK, Bind(self, self.OnEventSdkEvent))
    --GameUtils.SetRedPointNum(Constants.RedPointConst.WhiteLevelGift , 0)
    --GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.WhiteLevelGift)
    SetButtonAction(self.BtnExplain, function()
        CfUtils.ShowModuleToast(ToastModuleId)
    end)
    GameUtils.BindRedPoint(Constants.RedPointConst.WhiteLevelGiftButtonReward, self.AnmRoot, true)

    SetButtonAction(self.BtnReward, function()
        if whiteLevelGiftComponent.whiteLevelGiftTodayReceived == 0 then
            GameUtils.Request(Interfaces.MallWhiteLevelGiftDailyReceive, {}, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local data = checkTable(response.data)
                    whiteLevelGiftComponent:SetWhiteLevelGiftTodayReward(1)
                    self:FreshButtonState()
                    ---策划说充钱错不会再带有奖励
                    if isSet(data, "rewards") then
                        if table.count(checkTable(data.rewards)) > 0 then
                            GoodsUtils.DrawRewards(checkTable(data.rewards), true)
                            CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.UICommonRewardPop, parameters = {rewards = clone(data.rewards)}})
                        end
                    end
                end
            end)
        else
            GameUtils.Toast(localize('今天的奖励已领取'))
        end
    end)
end

function WhiteLevelGiftDialog:OnEventSdkEvent(parameters)
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        GameUtils.Request("OverseaMall/whiteLevelGift", {}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
                return
            end
            local data = checkTable(response.data)
            local t = {}
            local gifts = checkTable(data.whiteLevelGift)
            local preIndex = 0
            ---@type WhiteLevelGiftDojo
            local WhiteLevelGiftDojo = import('Game.Dojo.WhiteLevelGiftDojo')
            for index, v in pairs(gifts) do
                ---@type WhiteLevelGiftDojo
                local dojo = WhiteLevelGiftDojo.New()
                dojo:Fill(v)
                if preIndex > 0 then
                    dojo.preGift = gifts[preIndex]
                end
                preIndex = index
                table.insert(t, dojo)
            end
            ---@type WhiteLevelGiftComponent
            local whiteLevelGiftComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.WhiteLevelGiftComponent)
            whiteLevelGiftComponent.whiteLevelGift = t
            self.data = t
            --- sdk pay succeed
            self:Refresh(true)
        end)
    end
end

function WhiteLevelGiftDialog:RefreshRechargeTaskList_()
    -- reload list
    local rechargeTaskList = checkTable(self.data)
    local rechargeTaskSize = #rechargeTaskList
    -- check empty list
    if rechargeTaskSize == 0 then
        return
    end
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerLevel = checkNumber(playerComponent.playerDojo.level)
    table.sort(rechargeTaskList, function(a, b)
        local aKey = 10000
        local bKey = 10000
        if  checkNumber(a.hasBuy) == 0 then
            aKey = 1
        end
        if  checkNumber(b.hasBuy) == 0 then
            bKey = 1
        end
        if aKey == 1 and bKey == 1 then
            aKey = checkNumber(a.level)
            bKey = checkNumber(b.level)
        end
        if aKey == 10000 and bKey == 10000 then
            aKey = 1000 + checkNumber(a.level)
            bKey = 1000 + checkNumber(b.level)
            if checkNumber(a.hasBuy) == 1 then
                aKey = 5000 + checkNumber(a.level)
            end
            if checkNumber(b.hasBuy) == 1 then
                bKey = 5000 + checkNumber(b.level)
            end
        end
        return aKey < bKey
    end)
    self.cellTargetIndex = 0
    --for listIndex, listData in ipairs(rechargeTaskList) do
    --    if checkInt(listData.hasBuy) == 0 then
    --        self.cellTargetIndex = listIndex - 1
    --        break
    --    end
    --end

    if not self.ListView.IsListViewInit then
        self.ListView:InitListView(rechargeTaskSize, Bind(self, self.OnUpdateTaskListCellHandler_),{mTargetIndex = self.cellTargetIndex})
    else
        self.ListView:MovePanelToItemIndex(self.cellTargetIndex)
    end
end

function WhiteLevelGiftDialog:OnUpdateTaskListCellHandler_(listView, listIndex)
    if listIndex < 0 then return end
    local cell = listView:NewListViewItem("Cell")
    ---@type WhiteLevelGiftCellNode
    local nodeEnv = CfUtils.GetLuaScr(cell.gameObject, RechargeCellNodePath)
    if nodeEnv then
        local luaIndex = listIndex + 1
        local cellData = checkTable(self.data[luaIndex])
        -- init cell
        nodeEnv:SetLuaIndex(luaIndex)
        nodeEnv:SetClickCB(Bind(self, self.OnCellClickAction))
        nodeEnv:FreshUI(cellData, luaIndex)
    end
    return cell
end

---OnCellClickAction
---@param cellData WhiteLevelGiftDojo
---@param playerLevel number
function WhiteLevelGiftDialog:OnCellClickAction(cellData, playerLevel)
    if isNull(cellData) or checkNumber(cellData.hasBuy) == 1 then
        return
    end
    if cellData:IsGoodExchange() then
        local goodsId = checkNumber(table.takeFirst(table.keys(cellData.prices)))
        local dojo = cellData.prices[tostring(goodsId)]
        local productId = cellData.saleProduct.productId
        if dojo then
            local price = checkNumber(dojo.current)
            if checkNumber(cellData.saleRemainTime) <= 0 then
                ---要用原始价格去购买
                price = checkNumber(dojo.original)
                productId = cellData.sourceProduct.productId
            end
            ---@type ServerDifferenceMgr
            local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
            ServerDifferenceMgr:WrapPrimaryCurrencyBuy({
                currency = goodsId,
                current = price,
            }, function(isSuccess)
                isSuccess = checkBool(isSuccess)
                if not isSuccess then
                    return
                end
                ----请求兑换的逻辑
                GameUtils.Request(Interfaces.MallWhiteLevelGiftBuy, {
                    productId = productId,
                    num = 1,
                    currency = goodsId,
                }, function(request, resp)
                    if checkNumber(resp.errCode) == 0 then
                        local reward = checkTable(resp.data.rewards)
                        GoodsUtils.DrawRewards({ {
                                                     goodsId = goodsId,
                                                     num = - price,
                                                     productId = checkNumber(productId)
                                                 } })
                        if #reward > 0 then
                            GoodsUtils.DrawRewards(reward)
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = reward } })
                        end
                        GameUtils.Request("OverseaMall/whiteLevelGift", {}, function(_req, response)
                            if checkNumber(response.errCode) ~= 0 then
                                return
                            end
                            local data = checkTable(response.data)
                            local t = {}
                            local gifts = checkTable(data.whiteLevelGift)
                            local preIndex = 0
                            ---@type WhiteLevelGiftDojo
                            local WhiteLevelGiftDojo = import('Game.Dojo.WhiteLevelGiftDojo')
                            for index, v in pairs(gifts) do
                                ---@type WhiteLevelGiftDojo
                                local dojo = WhiteLevelGiftDojo.New()
                                dojo:Fill(v)
                                if preIndex > 0 then
                                    dojo.preGift = gifts[preIndex]
                                end
                                preIndex = index
                                table.insert(t, dojo)
                            end
                            -----@type WhiteLevelGiftDojo
                            --local WhiteLevelGiftDojo = import('Game.Dojo.WhiteLevelGiftDojo')
                            --for _, v in pairs(checkTable(data.whiteLevelGift)) do
                            --    ---@type WhiteLevelGiftDojo
                            --    local dojo = WhiteLevelGiftDojo.New()
                            --    dojo:Fill(v)
                            --    table.insert(t, dojo)
                            --end
                            ---@type WhiteLevelGiftComponent
                            local whiteLevelGiftComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.WhiteLevelGiftComponent)
                            whiteLevelGiftComponent.whiteLevelGift = t
                            self.data = t
                            --- sdk pay succeed
                            self:Refresh(true)
                        end)
                    end
                end)
            end)
        end
    else
        ---@type SDKService
        local SDKService = import('Game.Entry.SDKService')
        local productId = cellData.saleProduct.productId
        local channelProductId = cellData.saleProduct.channelProductId
        local price = cellData.saleProduct.price
        local data = cellData.saleProduct
        if checkNumber(cellData.saleRemainTime) <= 0 then
            ---要用原始价格去购买
            productId = cellData.sourceProduct.productId
            channelProductId = cellData.sourceProduct.channelProductId
            price = cellData.sourceProduct.price
            data = cellData.sourceProduct
        end
        SDKService:GetInstance():PayMoney({
            productId = productId,
            channelProductId = channelProductId,
            productDesc = localize('_num_级特惠礼包', { _num_ = checkNumber(playerLevel) }),
            payAmount = checkNumber(price),
            data = data
        })
    end
end

function WhiteLevelGiftDialog:Refresh(ignoreRecord)
    if not checkBool(ignoreRecord) then
        xRecord.record('4-009', 'click_lvl_pack')
    end
    self:RefreshRechargeTaskList_()
    self:FreshButtonState()
end

function WhiteLevelGiftDialog:FreshButtonState()
    ---@type WhiteLevelGiftComponent
    local whiteLevelGiftComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.WhiteLevelGiftComponent)
    if whiteLevelGiftComponent then
        CfUtils.SetActive(self.FX_glow2, whiteLevelGiftComponent.whiteLevelGiftTodayReceived == 0)
        CfUtils.SetUISwitchImage(self.ImgSymbol, whiteLevelGiftComponent.whiteLevelGiftTodayReceived == 1 and 1 or 2)
    end
end

function WhiteLevelGiftDialog:OnDestroy()
    if self.__EventSdkEvent then
        Events.RemoveListener(Constants.EventNames.EVENT_SDK, self.__EventSdkEvent)
        self.__EventSdkEvent = nil
    end
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.WhiteLevelGiftButtonReward)
    -- SettingModule.RemoveFileCacheByPath(AutoIds.IdSetting6201)
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return WhiteLevelGiftDialog